    # Build grid with 0-indexed coordinates
    grid = [[0] * N for _ in range(N)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        # Convert 1-indexed to 0-indexed
        grid[x - 1][y - 1] = val

    # Edge case: single cell
    if N == 1:
        return grid[0][0]

    # Initialize DP for step 0
    dp_prev = [[-10**18] * N for _ in range(N)]
    dp_prev[0][0] = grid[0][0]

    max_step = 2 * N - 2
    for k in range(1, max_step + 1):
        dp_cur = [[-10**18] * N for _ in range(N)]
        i_min = max(0, k - (N - 1))
        i_max = min(N - 1, k)
        for i1 in range(i_min, i_max + 1):
            j1 = k - i1
            if j1 < 0 or j1 >= N:
                continue
            for i2 in range(i_min, i_max + 1):
                j2 = k - i2
                if j2 < 0 or j2 >= N:
                    continue
                best = -10**18
                # Consider all combinations of previous moves
                for di1 in (0, 1):  # 0: came from left, 1: came from up
                    for di2 in (0, 1):
